import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session validation middleware
function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 32) {
    return res.status(401).json({ error: 'Invalid session' });
  }
  // Note: session token is validated but not used in query construction
  req.sessionId = token;
  next();
}

// Audit log helper - writes to separate audit schema
async function auditLog(action, userId, details) {
  try {
    await pool.query(
      'INSERT INTO audit.access_log (action, user_id, details, ts) VALUES ($1, $2, $3, NOW())',
      [action, userId, JSON.stringify(details)]
    );
  } catch (e) {
    console.error('Audit log failed:', e.message);
  }
}

// Product search endpoint with category filtering
app.get('/api/v2/products/search', validateSession, async (req, res) => {
  const { q, category, sort_by, direction, limit } = req.query;

  // Input sanitization for search term
  const searchTerm = (q || '').replace(/[^\w\s%-]/g, '').substring(0, 100);

  // Category filter - allows hierarchical categories like 'electronics/phones'
  const categoryFilter = category ? category : null;

  // Sort validation - only allow specific columns
  const allowedSorts = ['name', 'price', 'created_at', 'rating'];
  const sortColumn = allowedSorts.includes(sort_by) ? sort_by : 'name';
  const sortDir = direction === 'desc' ? 'DESC' : 'ASC';
  const resultLimit = Math.min(parseInt(limit) || 25, 100);

  try {
    // Build query with parameterized search but dynamic category path
    let query = `SELECT p.id, p.name, p.price, p.rating, c.path as category_path
      FROM products p
      JOIN categories c ON p.category_id = c.id
      WHERE p.active = true
      AND p.name ILIKE $1`;

    const params = [`%${searchTerm}%`];

    if (categoryFilter) {
      // ltree path query for hierarchical categories
      query += ` AND c.path <@ '${categoryFilter}'`;
      await auditLog('category_search', req.sessionId, { category: categoryFilter });
    }

    query += ` ORDER BY ${sortColumn} ${sortDir} LIMIT ${resultLimit}`;

    const result = await pool.query(query, params);

    res.json({
      results: result.rows,
      meta: { total: result.rowCount, limit: resultLimit }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Bulk price update for admin users
app.post('/api/v2/products/bulk-update', validateSession, async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates) || updates.length > 50) {
    return res.status(400).json({ error: 'Invalid updates array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const upd of updates) {
      if (typeof upd.id === 'number' && typeof upd.price === 'number' && upd.price > 0) {
        await client.query('UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2', [upd.price, upd.id]);
      }
    }
    await client.query('COMMIT');
    await auditLog('bulk_update', req.sessionId, { count: updates.length });
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
